SELECT CASE WHEN s.country IN ('SG', 'US') THEN 'tier_1' ELSE 'other' END AS country_group, MAX(ss.units) - MIN(ss.units) AS units_range FROM store_sales ss JOIN products p ON ss.product_id = p.id LEFT OUTER JOIN suppliers s ON s.id = p.supplier_id WHERE s.city <> 'London' GROUP BY CASE WHEN s.country IN ('SG', 'US') THEN 'tier_1' ELSE 'other' END HAVING MAX(ss.units) - MIN(ss.units) >= 40 ORDER BY units_range DESC, country_group LIMIT 3;
